package com.company.platform.analytics.application;
import com.company.platform.analytics.infrastructure.TenantContextProvider;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;
@Service public class ReportEngineService{private final JdbcTemplate jdbc;private final TenantContextProvider tenant;public ReportEngineService(JdbcTemplate j,TenantContextProvider t){jdbc=j;tenant=t;}private UUID t(){return tenant.currentTenantId();}private String dateWhere(String from,String to){return from!=null&&to!=null?" AND occurred_at BETWEEN ?::timestamptz AND ?::timestamptz ":"";}private List<Map<String,Object>> query(String sql,String from,String to){if(from!=null&&to!=null)return jdbc.queryForList(sql+" AND tenant_id=? AND occurred_at BETWEEN ?::timestamptz AND ?::timestamptz ORDER BY occurred_at DESC",t(),from,to);return jdbc.queryForList(sql+" AND tenant_id=? ORDER BY occurred_at DESC",t());}public List<Map<String,Object>> sales(String from,String to){return from!=null&&to!=null?jdbc.queryForList("SELECT * FROM analytics_sales WHERE tenant_id=? AND period_date BETWEEN ?::date AND ?::date ORDER BY period_date DESC",t(),from,to):jdbc.queryForList("SELECT * FROM analytics_sales WHERE tenant_id=? ORDER BY period_date DESC",t());}public List<Map<String,Object>> orders(String from,String to){return query("SELECT * FROM analytics_orders WHERE 1=1",from,to);}public List<Map<String,Object>> payments(String from,String to){return query("SELECT * FROM analytics_payments WHERE 1=1",from,to);}public List<Map<String,Object>> refunds(String from,String to){return query("SELECT * FROM analytics_refunds WHERE 1=1",from,to);}public List<Map<String,Object>> inventory(){return jdbc.queryForList("SELECT * FROM analytics_inventory WHERE tenant_id=? ORDER BY occurred_at DESC",t());}public List<Map<String,Object>> fulfillment(){return jdbc.queryForList("SELECT * FROM analytics_events WHERE tenant_id=? AND event_type LIKE 'Fulfillment%' ORDER BY occurred_at DESC",t());}}
